function dispatchRaceGraceMs(jobParams) {
    // gh-748: how long a COMPLETED run on the head still counts as
    // "may have just ordered CI" for the dispatch-race guard (the
    // Actions-API registration lag after gh workflow run returns).
    // Default 60s; jobParams.dispatchRaceGraceMs tunes it per
    // deployment; 0 disables the widened probe (legacy single-probe
    // guard).
    var n = (jobParams || {}).dispatchRaceGraceMs;
    n = typeof n === 'string' ? parseInt(n, 10) : n;
    if (typeof n !== 'number' || isNaN(n) || n < 0) return 60 * 1000;
    return Math.floor(n);
}
