function hasRecentHeadRun(runs, graceMs) {
    // gh-748 dispatch-race probe over the FULL head rollup (all
    // workflows, all events, all triggering actors): active now, or
    // completed within graceMs. A run that completed seconds ago is
    // exactly the registration-lag shape — its own CI child (a kicker
    // dispatch) may not be visible to the event-filtered probe yet.
    // Takes the pre-fetched head rollup (headWorkflowRunsSafe — a null
    // failed probe reads as no race — fail OPEN, matching
    // hasActiveDispatchedRun's error contract).
    var now = Date.now();
    return (runs || []).some(function (r) {
