        assert.equal(sm.capturedEnvSets.length, 0, 'no PAT swap — dispatch rides the ambient token');
        assert.equal(sm.capturedPrLabelAdds.length, 1);
        assert.equal(sm.capturedPrLabelAdds[0].number, 70);
