                          head_sha: 'bbbb0000bbbb', status: 'in_progress' },
                        { id: 444, event: 'workflow_dispatch', head_branch: 'ai/gh-77',
                          head_sha: 'dddd0000dddd', status: 'completed' }
                    ] };
                }
                return undefined;
            }
        }));
        sm.action({ jobParams: { owner: 'IstiN', repo: 'flutter_agent_harness',
