            defaults, 'no dispatched runs on the head → all defaults');

        var smFail = makeSmAgent(Object.assign(config('a', 'b'), {
            github: { items: [] },
            onCliExecute: function () { throw new Error('net down'); }
        }));
        assert.doesNotThrow(function () {
